def get_top3(prefix):
    n=root
    for c in prefix:
        if c not in n.ch: return []
        n=n.ch[c]
    results=[]
    def dfs(node,path):
        if node.is_end: results.append((-node.freq,path))
        for c in sorted(node.ch): dfs(node.ch[c],path+c)
